-- ----------------------------
-- Table structure for pms_knowledge_document
-- ----------------------------
DROP TABLE IF EXISTS `pms_knowledge_document`;
CREATE TABLE `pms_knowledge_document`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '文档编号',
  `library_id` bigint NOT NULL COMMENT '知识库编号',
  `permission_id` bigint NOT NULL COMMENT '内容协作权限编号',
  `folder_id` bigint NOT NULL DEFAULT 0 COMMENT '文件夹编号，0 表示不在文件夹中',
  `parent_id` bigint NOT NULL DEFAULT 0 COMMENT '父文档编号，0 表示根文档',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '文档标题',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '文档内容或文件地址',
  `type` int NOT NULL COMMENT '文档类型，3 富文本，4 文件',
  `file_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '文件类型',
  `file_size` bigint NULL DEFAULT NULL COMMENT '文件大小（字节）',
  `status` int NOT NULL DEFAULT 1 COMMENT '状态，-1 回收站，0 草稿，1 正常，2 模板',
  `label_ids` varchar(5000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '标签编号列表',
  `delete_user_id` bigint NULL DEFAULT NULL COMMENT '删除人用户编号',
  `delete_time` datetime NULL DEFAULT NULL COMMENT '删除时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_library_folder_parent_status`(`library_id` ASC, `folder_id` ASC, `parent_id` ASC, `status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9106 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'PMS 知识库文档';

-- ----------------------------
-- Records of pms_knowledge_document
-- ----------------------------
BEGIN;
INSERT INTO `pms_knowledge_document` (`id`, `library_id`, `permission_id`, `folder_id`, `parent_id`, `title`, `content`, `type`, `file_type`, `file_size`, `status`, `label_ids`, `delete_user_id`, `delete_time`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`) VALUES (1, 1, 1, 0, 0, '2020.01.01 更新日志', '<div id=\"wk-knowledge-title-wukong\">\n<p id=\"wk-knowledge-content-wukong\">2020.01.01 更新日志</p>\n</div>\n<p style=\"mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-pagination: widow-orphan;\">按钮（可上传图片）</p>\n<p style=\"mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-pagination: widow-orphan;\">封面图片</p>\n<h1 style=\"mso-pagination: widow-orphan;\">新功能</h1>\n<p class=\"MsoNormal\" style=\"margin-left: 21.0pt; text-align: left; text-indent: -21.0pt; mso-pagination: widow-orphan; mso-list: l1 level1 lfo1;\" align=\"left\"><!-- [if !supportLists]--><span lang=\"EN-US\"><span style=\"mso-list: Ignore;\">l<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal;\">&nbsp; </span></span></span><!--[endif]-->新功能点</p>\n<h1 style=\"mso-pagination: widow-orphan;\">优化项<a name=\"_GoBack\"></a></h1>\n<p class=\"MsoNormal\" style=\"margin-left: 21.0pt; text-align: left; text-indent: -21.0pt; mso-pagination: widow-orphan; mso-list: l2 level1 lfo2;\" align=\"left\"><!-- [if !supportLists]--><span lang=\"EN-US\"><span style=\"mso-list: Ignore;\">l<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal;\">&nbsp; </span></span></span><!--[endif]-->优化内容</p>\n<h1 style=\"mso-pagination: widow-orphan;\"><span lang=\"EN-US\">Bug </span>修复</h1>\n<p class=\"MsoNormal\" style=\"margin-left: 21.0pt; text-align: left; text-indent: -21.0pt; mso-pagination: widow-orphan; mso-list: l0 level1 lfo3;\" align=\"left\"><!-- [if !supportLists]--><span lang=\"EN-US\"><span style=\"mso-list: Ignore;\">l<span style=\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal;\">&nbsp; </span></span></span><!--[endif]-->修复内容</p>\n<p class=\"MsoNormal\"><span lang=\"EN-US\">&nbsp;</span></p>', 3, NULL, NULL, 1, NULL, NULL, NULL, '1', '2026-08-19 08:14:16', '1', '2026-08-19 08:14:16', b'0', 1), (2, 2, 15, 1, 0, '产品需求文档模板', '<h1>产品需求文档</h1><h2>背景与目标</h2><p>描述用户问题、业务目标和衡量指标。</p><h2>用户故事</h2><ul><li>作为用户，我希望快速完成核心操作。</li><li>作为运营，我希望追踪功能效果。</li></ul><h2>验收标准</h2><p>列出清晰、可验证的验收条件。</p>', 3, NULL, NULL, 1, '1,6', NULL, NULL, '1', '2026-08-19 08:24:37', '1', '2026-08-22 21:59:52', b'0', 1), (3, 2, 16, 1, 0, '电商 App 2.0 交互规范', '<h1>移动端交互规范</h1><p>统一导航、弹窗、表单、加载和异常反馈的交互方式。</p><h2>基本原则</h2><ol><li>关键动作可撤销</li><li>状态反馈及时明确</li><li>弱网场景提供降级体验</li></ol>', 3, NULL, NULL, 1, '1,5', NULL, NULL, '1', '2026-08-19 08:24:37', '1', '2026-08-22 21:59:52', b'0', 1), (4, 2, 17, 2, 0, '需求评审流程', '<h1>需求评审流程</h1><p>需求进入开发前，需要依次完成产品自审、技术评审和测试评审。</p><h2>输出物</h2><ul><li>确认后的 PRD</li><li>技术方案</li><li>测试范围与风险清单</li></ul>', 3, NULL, NULL, 1, '1,3', NULL, NULL, '1', '2026-08-19 08:24:37', '1', '2026-08-22 21:59:52', b'0', 1), (5, 2, 18, 2, 0, '代码评审检查清单', '<h1>代码评审检查清单</h1><ul><li>业务边界是否完整</li><li>是否存在重复查询</li><li>异常信息是否清晰</li><li>测试是否覆盖关键分支</li><li>是否有安全与性能风险</li></ul>', 3, NULL, NULL, 1, '2,3', NULL, NULL, '1', '2026-08-19 08:24:37', '1', '2026-08-22 21:59:52', b'0', 1), (6, 2, 19, 3, 0, '版本发布检查清单', '<h1>版本发布检查清单</h1><p>发布负责人逐项确认数据库、配置、灰度、监控和回滚方案。</p><h2>发布后</h2><p>观察错误率、接口耗时、订单转化和用户反馈。</p>', 3, NULL, NULL, 1, '3,5', NULL, NULL, '1', '2026-08-19 08:24:37', '1', '2026-08-22 21:59:52', b'0', 1), (7, 2, 20, 3, 0, 'Sprint 02 复盘纪要', '<h1>Sprint 02 复盘</h1><h2>做得好的</h2><p>结算链路提前完成联调。</p><h2>需要改进</h2><p>需求变更应更早同步测试范围。</p><h2>行动项</h2><p>为高风险需求增加发布前检查会。</p>', 3, NULL, NULL, 1, '4,5', NULL, NULL, '1', '2026-08-19 08:24:37', '1', '2026-08-22 21:59:52', b'0', 1), (8, 2, 21, 1, 0, '会员权益方案草稿', '<h1>会员权益方案</h1><p>该文档仍在讨论中，暂不作为正式方案。</p>', 3, NULL, NULL, 0, '1,6', NULL, NULL, '1', '2026-08-19 08:24:37', '1', '2026-08-22 21:59:52', b'0', 1), (9, 2, 22, 13, 0, '旧版需求流转说明', '<h1>旧版需求流转</h1><p>此流程已经废弃，保留在回收站用于演示恢复功能。</p>', 3, NULL, NULL, -1, NULL, 1, '2026-08-18 08:24:37', '1', '2026-08-19 08:24:37', '1', '2026-08-19 08:24:37', b'0', 1), (10, 3, 23, 4, 0, 'PMS 模块分层设计', '<h1>PMS 模块分层设计</h1><p>Controller 负责 VO 转换，Service 承载业务编排，Mapper 聚焦数据访问。</p><h2>跨聚合原则</h2><p>跨聚合调用 Service，跨模块调用 API，避免直接依赖其他聚合 Mapper。</p>', 3, NULL, NULL, 1, '2,5', NULL, NULL, '1', '2026-08-19 08:24:37', '1', '2026-08-22 21:59:52', b'0', 1), (11, 3, 24, 4, 0, '接口幂等设计指南', '<h1>接口幂等设计</h1><p>创建类接口应根据业务编号或幂等令牌识别重复请求。</p><h2>常用方案</h2><ul><li>唯一索引</li><li>状态机校验</li><li>分布式锁</li></ul>', 3, NULL, NULL, 1, '2,3', NULL, NULL, '1', '2026-08-19 08:24:37', '1', '2026-08-22 21:59:52', b'0', 1), (12, 3, 25, 5, 0, 'Vue 页面开发约定', '<h1>Vue 页面开发约定</h1><p>列表页统一使用查询表单、表格、分页和 Dialog 结构。</p><p>公共选择器优先复用 System、CRM 和现有业务组件。</p>', 3, NULL, NULL, 1, '2,3', NULL, NULL, '1', '2026-08-19 08:24:37', '1', '2026-08-22 21:59:52', b'0', 1), (13, 3, 26, 5, 0, '前端性能检查清单', '<h1>前端性能检查</h1><ul><li>避免无意义的重复请求</li><li>大列表按需分页</li><li>图片启用合适尺寸</li><li>路由组件按需加载</li></ul>', 3, NULL, NULL, 1, '2,3', NULL, NULL, '1', '2026-08-19 08:24:37', '1', '2026-08-22 21:59:52', b'0', 1), (14, 3, 27, 6, 0, '生产发布与回滚手册', '<h1>生产发布与回滚手册</h1><h2>发布前</h2><p>确认制品、配置、数据库脚本和监控面板。</p><h2>回滚条件</h2><p>错误率或核心业务指标超过阈值时立即回滚。</p>', 3, NULL, NULL, 1, '3,5', NULL, NULL, '1', '2026-08-19 08:24:37', '1', '2026-08-22 21:59:52', b'0', 1), (15, 3, 28, 6, 0, '架构参考附件.pdf', 'http://test.yudao.iocoder.cn/crm/followup/20260615/reference.pdf', 4, 'application/pdf', NULL, 1, '2', NULL, NULL, '1', '2026-08-19 08:24:37', '1', '2026-08-22 21:59:52', b'0', 1), (16, 4, 29, 7, 0, '客户项目启动清单', '<h1>客户项目启动清单</h1><ul><li>明确项目目标和范围</li><li>确认双方项目成员</li><li>建立沟通与升级机制</li><li>确定里程碑及验收标准</li></ul>', 3, NULL, NULL, 1, '3,5', NULL, NULL, '1', '2026-08-19 08:24:37', '1', '2026-08-22 21:59:52', b'0', 1), (17, 4, 30, 7, 0, '上线验收报告模板', '<h1>上线验收报告</h1><h2>验收范围</h2><p>填写本次交付模块和版本。</p><h2>验收结果</h2><p>记录测试、培训、数据和上线确认结论。</p>', 3, NULL, NULL, 1, '3,6', NULL, NULL, '1', '2026-08-19 08:24:37', '1', '2026-08-22 21:59:52', b'0', 1), (18, 4, 31, 8, 0, '管理员培训大纲', '<h1>管理员培训大纲</h1><ol><li>组织与账号配置</li><li>角色和权限配置</li><li>核心业务操作</li><li>数据导入导出</li><li>常见问题排查</li></ol>', 3, NULL, NULL, 1, '3', NULL, NULL, '1', '2026-08-19 08:24:37', '1', '2026-08-22 21:59:52', b'0', 1), (19, 4, 32, 8, 0, '培训签到与反馈表.xlsx', 'http://test.yudao.iocoder.cn/fms/voucher/import/20260811/%E5%87%AD%E8%AF%81%E5%AF%BC%E5%85%A5%E9%94%99%E8%AF%AF%E6%95%B0%E6%8D%AE.xlsx', 4, 'xlsx', NULL, 1, '3', NULL, NULL, '1', '2026-08-19 08:24:37', '1', '2026-08-26 14:17:31', b'0', 1), (20, 4, 33, 9, 0, '无法收到通知怎么办', '<h1>无法收到通知怎么办</h1><p>依次检查账号状态、消息模板、接收渠道、网络和发送日志。</p><p>仍无法解决时，请提供问题时间、账号和操作截图。</p>', 3, NULL, NULL, 1, '3', NULL, NULL, '1', '2026-08-19 08:24:37', '1', '2026-08-22 21:59:52', b'0', 1), (21, 4, 34, 9, 0, '常见权限问题排查', '<h1>权限问题排查</h1><ol><li>确认用户是否在正确租户</li><li>确认角色是否包含菜单权限</li><li>确认数据是否属于当前业务范围</li><li>重新登录刷新权限缓存</li></ol>', 3, NULL, NULL, 1, '3,2', NULL, NULL, '1', '2026-08-19 08:24:37', '1', '2026-08-22 21:59:52', b'0', 1), (22, 5, 35, 10, 0, '品牌视觉使用规范', '<h1></h1><p>统一 Logo、安全距离、标准色、字体和图片风格。</p><h2>禁止事项</h2><p>不得拉伸 Logo、随意修改颜色或在复杂背景上直接使用。</p>', 3, NULL, NULL, 1, '1,5', NULL, NULL, '1', '2026-08-19 08:24:37', '1', '2026-08-26 15:32:19', b'0', 1), (23, 5, 36, 10, 0, '对外文案语气指南', '<h1>对外文案语气指南</h1><p>表达应清晰、可信、友好，避免夸张承诺和无依据的数据。</p><p>标题优先说明用户收益，正文提供可执行的信息。</p><p><br></p><p>发送发送分鹅鹅鹅饿</p>', 3, NULL, NULL, 1, '1,3', NULL, NULL, '1', '2026-08-19 08:24:37', '1', '2026-08-26 10:16:27', b'0', 1), (24, 5, 37, 11, 0, '秋季发布会活动方案', '<h1>秋季发布会活动方案</h1><h2>活动目标</h2><p>发布年度重点产品并沉淀潜在客户线索。</p><h2>核心环节</h2><ul><li>主题演讲</li><li>产品演示</li><li>客户案例</li><li>圆桌交流</li></ul>', 3, NULL, NULL, 1, '1,5', NULL, NULL, '1', '2026-08-19 08:24:37', '1', '2026-08-22 21:59:52', b'0', 1), (25, 5, 38, 11, 0, '社交媒体内容排期', '<h1>社交媒体内容排期</h1><p>每周覆盖产品价值、客户案例、行业观点和团队故事四类内容。</p>', 3, NULL, NULL, 0, '3,6', NULL, NULL, '1', '2026-08-19 08:24:37', '1', '2026-08-22 21:59:52', b'0', 1), (26, 5, 39, 12, 0, '春季品牌活动复盘', '<h1>春季品牌活动复盘</h1><p>报名与到场率达到目标，客户案例内容传播效果最好。</p><h2>改进行动</h2><p>下一场活动提前两周完成嘉宾确认和演示彩排。</p>', 3, NULL, NULL, 1, '4,5', NULL, NULL, '1', '2026-08-19 08:24:37', '1', '2026-08-22 21:59:52', b'0', 1), (9101, 2, 9102, 1, 0, '旧版原型设计说明', '<p>旧版原型设计说明，仅用于回收站体验。</p>', 3, NULL, NULL, -1, NULL, 1, '2026-08-25 08:35:00', '1', '2026-06-11 10:00:00', '1', '2026-08-25 08:35:00', b'0', 1), (9102, 3, 9104, 4, 0, '早期缓存架构评审', '<p>早期缓存架构方案，已由新版设计替代。</p>', 3, NULL, NULL, -1, NULL, 1, '2026-08-24 12:40:00', '1', '2026-05-09 11:00:00', '1', '2026-08-24 12:40:00', b'0', 1), (9103, 4, 9105, 7, 0, '旧客户上线检查表', '<p>历史客户上线检查表。</p>', 3, NULL, NULL, -1, NULL, 1, '2026-08-23 17:15:00', '1', '2026-04-18 14:00:00', '1', '2026-08-23 17:15:00', b'0', 1), (9104, 5, 9106, 11, 0, '春季活动废弃文案', '<p>未采用的春季活动宣传文案。</p>', 3, NULL, NULL, -1, NULL, 1, '2026-08-22 10:30:00', '1', '2026-03-20 09:30:00', '1', '2026-08-22 10:30:00', b'0', 1), (9105, 5, 9107, 0, 0, '临时验证文档', NULL, 3, NULL, NULL, -1, NULL, 1, '2026-08-26 14:04:38', '1', '2026-08-26 13:57:37', '1', '2026-08-26 14:04:41', b'1', 1);
COMMIT;

-- ----------------------------
-- Table structure for pms_knowledge_document_comment
-- ----------------------------
DROP TABLE IF EXISTS `pms_knowledge_document_comment`;
CREATE TABLE `pms_knowledge_document_comment`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '评论编号',
  `document_id` bigint NOT NULL COMMENT '文档编号',
  `user_id` bigint NOT NULL COMMENT '评论人用户编号',
  `main_id` bigint NOT NULL DEFAULT 0 COMMENT '主评论编号，0 表示主评论',
  `reply_user_id` bigint NULL DEFAULT NULL COMMENT '回复对象用户编号',
  `content` varchar(2000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '评论内容',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_document_id_create_time`(`document_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_main_id`(`main_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 23 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'PMS 知识库文档评论';

-- ----------------------------
-- Records of pms_knowledge_document_comment
-- ----------------------------
BEGIN;
