INSERT INTO `pms_knowledge_library_template` (`id`, `name`, `description`, `cover_url`, `status`, `sort`, `documents`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`) VALUES (1, '产品研发', '提供完善的产品流程文档', 'http://127.0.0.1:48089/admin-api/infra/file/4/get/20260901/exec-196e56a5-34d5-48d4-9434-ab6b6f895be9.png', 0, 10, '[{\"title\": \"产品需求文档\", \"content\": \"\\n<p>产品需求文档</p>\\n<h1 style=\\\"mso-pagination: widow-orphan;\\\">基本信息</h1>\\n<p style=\\\"mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-pagination: widow-orphan;\\\">目标上线时间：请输入时间</p>\\n<p style=\\\"mso-margin-top-alt: auto; mso-margin-bottom-alt: auto; mso-pagination: widow-orphan;\\\"><span lang=\\\"EN-US\\\">&nbsp;</span></p>\\n<h1 style=\\\"mso-pagination: widow-orphan;\\\">项目人员</h1>\\n<p class=\\\"MsoNormal\\\" style=\\\"margin-left: 21.0pt; text-align: left; text-indent: -21.0pt; mso-pagination: widow-orphan; mso-list: l0 level1 lfo1;\\\" align=\\\"left\\\"><span lang=\\\"EN-US\\\"><span style=\\\"mso-list: Ignore;\\\">l<span style=\\\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal;\\\">&nbsp; </span></span></span>产品：请输入人员</p>\\n<p class=\\\"MsoNormal\\\" style=\\\"margin-left: 21.0pt; text-align: left; text-indent: -21.0pt; mso-pagination: widow-orphan; mso-list: l0 level1 lfo1;\\\" align=\\\"left\\\"><span lang=\\\"EN-US\\\"><span style=\\\"mso-list: Ignore;\\\">l<span style=\\\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal;\\\">&nbsp; </span></span></span>设计：请输入人员</p>\\n<p class=\\\"MsoNormal\\\" style=\\\"margin-left: 21.0pt; text-align: left; text-indent: -21.0pt; mso-pagination: widow-orphan; mso-list: l0 level1 lfo1;\\\" align=\\\"left\\\"><span lang=\\\"EN-US\\\"><span style=\\\"mso-list: Ignore;\\\">l<span style=\\\"font-style: normal; font-variant: normal; font-stretch: normal; line-height: normal;\\\">&nbsp; </span></span></span>研发：请输入人员</p>\\n<p class=\\\"MsoNormal\\\" style=\\\"marg