-- ----------------------------
-- Table structure for pms_knowledge_view_record
-- ----------------------------
DROP TABLE IF EXISTS `pms_knowledge_view_record`;
CREATE TABLE `pms_knowledge_view_record`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '浏览记录编号',
  `library_id` bigint NOT NULL COMMENT '知识库编号',
  `type` int NOT NULL COMMENT '对象类型，2 文件夹，3 文档，4 文件',
  `entity_id` bigint NOT NULL COMMENT '对象编号',
  `user_id` bigint NOT NULL COMMENT '用户编号',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_tenant_user_create_time_id`(`tenant_id` ASC, `user_id` ASC, `create_time` ASC, `id` ASC) USING BTREE,
  INDEX `idx_tenant_library_create_time_id`(`tenant_id` ASC, `library_id` ASC, `create_time` ASC, `id` ASC) USING BTREE,
  INDEX `idx_tenant_type_entity`(`tenant_id` ASC, `type` ASC, `entity_id` ASC) USING BTREE,
  INDEX `idx_tenant_user_type_entity`(`tenant_id` ASC, `user_id` ASC, `type` ASC, `entity_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 269 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'PMS 知识最近浏览记录';

