-- ----------------------------
-- Table structure for pms_project
-- ----------------------------
DROP TABLE IF EXISTS `pms_project`;
CREATE TABLE `pms_project`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '项目编号',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '项目名称',
  `status` int NOT NULL DEFAULT 1 COMMENT '项目状态，1 进行中，2 已归档，3 回收站',
  `type` int NOT NULL COMMENT '项目类型，1 通用项目，2 敏捷开发项目',
  `level` int NOT NULL COMMENT '优先级，1 最高，2 较高，3 普通，4 较低，5 最低',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '项目描述',
  `open_status` bit(1) NOT NULL DEFAULT b'1' COMMENT '是否公开',
  `icon` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '项目图标',
  `sort` int NULL DEFAULT NULL COMMENT '显示顺序',
  `start_time` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '截止时间',
  `archive_time` datetime NULL DEFAULT NULL COMMENT '归档时间',
  `recycle_time` datetime NULL DEFAULT NULL COMMENT '移入回收站时间',
  `access_time` datetime NULL DEFAULT NULL COMMENT '最近访问时间',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_status_access_time`(`status` ASC, `access_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 9 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'PMS 项目';

-- ----------------------------
-- Records of pms_project
-- ----------------------------
BEGIN;
INSERT INTO `pms_project` (`id`, `name`, `status`, `type`, `level`, `description`, `open_status`, `icon`, `sort`, `start_time`, `end_time`, `archive_time`, `recycle_time`, `access_time`, `creator`, `create_time`, `updater`, `update_time`, `deleted`, `tenant_id`) VALUES (1, 'PMS 迁移联调项目', 3, 1, 3, '验证项目档案、成员与生命周期流转', b'0', 'ep:folder', 0, NULL, NULL, NULL, '2026-08-18 22:37:41', '2026-08-18 22:33:54', '1', '2026-08-18 22:33:54', '1', '2026-08-18 22:38:21', b'1', 1), (3, '电商 App 2.0', 1, 2, 1, '围绕新版首页、购物车、结算链路和会员中心完成移动端 2.0 升级。', b'1', 'ep:shopping-cart', 10, '2026-07-01 09:00:00', '2026-10-31 18:00:00', NULL, NULL, '2026-09-03 01:51:40', '1', '2026-08-19 08:24:36', '1', '2026-09-03 01:51:40', b'0', 1), (4, '企业官网改版', 1, 1, 3, '重构品牌官网的信息架构、视觉体系、内容生产和上线流程。', b'1', 'ep:monitor', 20, '2026-08-01 09:00:00', '2026-09-30 18:00:00', NULL, NULL, '2026-09-02 18:13:01', '1', '2026-08-19 08:24:36', '1', '2026-09-02 18:13:01', b'0', 1), (5, '数据中台一期', 1, 2, 2, '统一指标口径，建设用户、订单和商品主题数据集及经营驾驶舱。', b'0', 'ep:data-analysis', 30, '2026-06-15 09:00:00', '2026-11-30 18:00:00', NULL, NULL, '2026-08-28 10:34:02', '1', '2026-08-19 08:24:36', '1', '2026-08-28 10:34:02', b'0', 1), (6, '客户成功体系建设', 1, 1, 3, '梳理客户交付、培训、健康度跟踪和续费预警的标准作业流程。', b'1', 'ep:service', 40, '2026-08-10 09:00:00', '2026-12-15 18:00:00', NULL, NULL, '2026-09-02 20:47:03', '1', '2026-08-19 08:24:36', '1', '2026-09-02 20:47:03', b'0', 1), (7, '2026 春季品牌活动', 2, 1, 4, '已完成的春季品牌活动，用于体验归档项目及历史任务。', b'1', 'ep:promotion', 50, '2026-02-01 09:00:00', '2026-04-30 18:00:00', '2026-05-06 10:00:00', NULL, '2026-07-15 08:24:36', '1', '2026-08-19 08:24:36', '1', '2026-08-19 08:24:36', b'0', 1), (8, '移动端旧版下线', 3, 1, 5, '已移入回收站的演示项目，可用于体验恢复和彻底删除。', b'0', 'ep:delete', 60, '2026-01-05 09:00:00', '2026-03-31 18:00:00', NULL, '2026-08-17 08:24:36', '2026-08-07 08:24:36', '1', '2026-08-19 08:24:36', '1', '2026-08-19 08:24:36', b'0', 1);
COMMIT;

-- ----------------------------
-- Table structure for pms_project_announcement
-- ----------------------------
DROP TABLE IF EXISTS `pms_project_announcement`;
CREATE TABLE `pms_project_announcement`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '公告编号',
  `project_id` bigint NOT NULL COMMENT '项目编号',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '公告内容',
  `file_urls` json NULL COMMENT '附件地址列表',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_project_id_create_time`(`project_id` ASC, `create_time` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'PMS 项目公告';

