-- ----------------------------
-- Table structure for pms_project_group
-- ----------------------------
DROP TABLE IF EXISTS `pms_project_group`;
CREATE TABLE `pms_project_group`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '项目分组编号',
  `user_id` bigint NOT NULL COMMENT '后台用户编号',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '分组名称',
  `sort` int NOT NULL DEFAULT 0 COMMENT '显示顺序',
  `type` tinyint NOT NULL DEFAULT 3 COMMENT '分组类型，1 全部项目，2 未分组，3 自定义分组',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id_type`(`user_id` ASC, `type` ASC) USING BTREE,
  INDEX `idx_user_id_sort`(`user_id` ASC, `sort` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 14 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'PMS 个人项目分组';

