-- ----------------------------
-- Table structure for pms_work_item
-- ----------------------------
DROP TABLE IF EXISTS `pms_work_item`;
CREATE TABLE `pms_work_item`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '工作项编号',
  `project_id` bigint NOT NULL COMMENT '项目编号',
  `type` int NOT NULL COMMENT '工作项类型，2 需求，3 任务，4 缺陷',
  `serial_number` int NOT NULL COMMENT '项目内工作项序号',
  `name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '工作项标题',
  `description` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL COMMENT '工作项描述',
  `priority` int NOT NULL COMMENT '优先级，0 无，1 低，2 中，3 高',
  `assignee_user_id` bigint NULL DEFAULT NULL COMMENT '负责人用户编号',
  `status_id` bigint NOT NULL COMMENT '看板状态编号',
  `status` int NOT NULL COMMENT '语义状态，1 未开始，2 进行中，3 已完成',
  `lifecycle_status` int NOT NULL DEFAULT 1 COMMENT '生命周期状态，1 正常，2 已归档，3 回收站',
  `archive_time` datetime NULL DEFAULT NULL COMMENT '归档时间',
  `recycle_time` datetime NULL DEFAULT NULL COMMENT '移入回收站时间',
  `iteration_id` bigint NULL DEFAULT NULL COMMENT '所属迭代编号',
  `parent_id` bigint NULL DEFAULT NULL COMMENT '父工作项编号',
  `related_requirement_id` bigint NULL DEFAULT NULL COMMENT '关联需求编号',
  `defect_type` int NULL DEFAULT NULL COMMENT '缺陷类型，1 功能，2 界面，3 易用性，4 安全，5 性能，6 代码错误',
  `start_time` datetime NULL DEFAULT NULL COMMENT '开始时间',
  `end_time` datetime NULL DEFAULT NULL COMMENT '截止时间',
  `estimated_hours` int NULL DEFAULT NULL COMMENT '预估工时，单位：小时',
  `progress` int NOT NULL DEFAULT 0 COMMENT '完成进度，取值范围 0-100',
  `file_urls` json NULL COMMENT '附件地址列表',
  `label_ids` json NULL COMMENT '标签编号列表',
  `sort` int NOT NULL DEFAULT 0 COMMENT '看板内显示顺序',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_project_id_serial_number_deleted`(`project_id` ASC, `serial_number` ASC, `deleted` ASC) USING BTREE,
  INDEX `idx_iteration_id`(`iteration_id` ASC) USING BTREE,
  INDEX `idx_assignee_user_id`(`assignee_user_id` ASC) USING BTREE,
  INDEX `idx_parent_id`(`parent_id` ASC) USING BTREE,
  INDEX `idx_related_requirement_id`(`related_requirement_id` ASC) USING BTREE,
  INDEX `idx_project_id_type_lifecycle_status_sort`(`project_id` ASC, `type` ASC, `lifecycle_status` ASC, `status_id` ASC, `sort` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 40 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'PMS 工作项';

