-- ----------------------------
-- Table structure for pms_work_item_activity
-- ----------------------------
DROP TABLE IF EXISTS `pms_work_item_activity`;
CREATE TABLE `pms_work_item_activity`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '动态编号',
  `project_id` bigint NOT NULL COMMENT '项目编号',
  `work_item_id` bigint NOT NULL COMMENT '工作项编号',
  `operator_user_id` bigint NOT NULL COMMENT '操作人用户编号',
  `content` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '动态内容',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_work_item_id_create_time`(`work_item_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_project_id`(`project_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 61 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'PMS 工作项动态';

