  INDEX `idx_work_item_id_create_time`(`work_item_id` ASC, `create_time` ASC) USING BTREE,
  INDEX `idx_main_id`(`main_id` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 19 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'PMS 工作项评论';

