-- ----------------------------
-- Table structure for pms_work_item_status
-- ----------------------------
DROP TABLE IF EXISTS `pms_work_item_status`;
CREATE TABLE `pms_work_item_status`  (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '状态编号',
  `project_id` bigint NOT NULL COMMENT '项目编号',
  `work_item_type` int NOT NULL COMMENT '工作项类型，2 需求，3 任务，4 缺陷',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '状态名称',
  `status_type` int NOT NULL COMMENT '语义状态，1 未开始，2 进行中，3 已完成',
  `description` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '状态描述',
  `board_name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '所属看板列名称，为空时不在看板展示',
  `system_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL COMMENT '系统状态编码，仅默认状态使用',
  `default_status` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否初始状态',
  `sort` int NOT NULL DEFAULT 0 COMMENT '显示顺序',
  `creator` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '创建者',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updater` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '' COMMENT '更新者',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` bit(1) NOT NULL DEFAULT b'0' COMMENT '是否删除',
  `tenant_id` bigint NOT NULL DEFAULT 0 COMMENT '租户编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `uk_tenant_project_type_system_code`(`tenant_id` ASC, `project_id` ASC, `work_item_type` ASC, `system_code` ASC) USING BTREE,
  INDEX `idx_project_id_type_sort`(`project_id` ASC, `work_item_type` ASC, `sort` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 29 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci COMMENT = 'PMS 工作项看板状态';

